INSERT INTO projects (project_id,site_id,project,status,date,capacity_note,water_change,source_id) VALUES ('P049-03','CN0211','催化剂车间洗涤水过滤罐基础及管线安装','2026-09采购索引，成交/投运未核','2026-09-27','非产能','过滤罐设备安装线索，未证滤材或膜；未核是否原载钯线','S049-13');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N049-01','CN0194','S049-01','历史验收实测与排放核算','2.4.2 表2.4-6/7','备用政府路径同S029-01；2023-11-22/23验收转录共享污水站实测12项；一二期11584.48m³/a、三期未建预测1940。表2.4-7 COD两行分别0.58/0.1/0.68与4.63/0.78/5.41t/a，原边界不清不结构化；其他负荷保留。共享站工艺前期资料矛盾未解除，不能据排口值证明MBR运行。PDF截图404，采用正文。','WEB_PRIMARY','公开正文或截图核对，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N049-02','CN0194','S049-02','废油许可边界','2025-12-10核发公示','HW08废矿物油经营规模10万吨/年，不是废催化剂许可，更非催化剂实际产能；不解除2026工艺核查。','WEB_PRIMARY','公开正文或截图核对，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N049-03','CN0211','W03S34','原图与报告日期纠正','封面2022-03、表2-1、4.5、图4-8和表4-7；PDF页48/49截图','2023公开上传不等于编制年，2022-03自行监测方案。载钯生产能力240t/a；4股载钯水和研发、公辅分别入全厂共享站，格栅、调节、进水、沉淀、气浮、出水、活性炭，生活经化粪池后总排口。2022历史工程，不证2026运行；未得站能力及分股量。','WEB_PRIMARY','公开正文或截图核对，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N049-04','CN0211','S049-13','新过滤罐安装线索','7284-PS202609270083公告转载','2026-09催化剂车间洗涤水过滤罐基础、管线安装；不证明为膜或已完成，具体车间及设备规格未知。','WEB_SECONDARY','公开正文或截图核对，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N049-05','CN0003','W01B2S04','历史电渗析回收与试运行','7.2.1 图7.2-1及pp145–148 表7.2-1','晶化及二次改性水酸调pH7、约60℃陈化、板框、膜分离、冷却43℃，与一次改性过滤水入ED。脱盐ED三并联膜堆，浓水进入双极膜两并联膜堆，稀盐酸返回预处理、稀TPAOH提浓ED两并联膜堆后双极膜提纯回主体装置；淡水回用或后续处理，报告又称纳站，具体支路待核。膜分离种类未指明。表试运行出水COD905、BOD332mg/L，表末列400/300但正文称满足，保留冲突，不能独立判断达标；年量t/a与正文m³/a不互换。截图失败，用正文。','WEB_PRIMARY','公开正文或截图核对，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N049-06','CN0003','W01B2S04','历史共享站监测','表7.2-2 pp149–150','2018-12-14/15四次八指标及原表日均/范围；L为低于检出限，不取0。监测期间50m³/h、表设计200m³/h，正文200t/h。SS表两日均25，正文称最大35，不自行改原值；共享排口非ED出水。非2026实况。','WEB_PRIMARY','公开正文或截图核对，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N049-07','CN0249','S049-03','新装置验收公示','2026-08-24至09-20企业公示','凤凰山路以东、青银高速以南、G309以北新厂区，单条废丁烯氧化脱氢催化剂再生线500t/a处理，499.84t/a产出。附件网盘未获取；仅公示存在，不能声称废水监测、膜工艺或验收结论；与S020-001废苯酐项目分开。','WEB_COMPANY','公开正文或截图核对，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N049-08','CN0127','S049-12','新验收服务采购','2026-11采购单P-XJ-20261119-000026转载','要求制定验收方案、监测、报告和评审；报价截止11-25；采购不等于设施已验收，不确认膜浓缩设备投运。','WEB_SECONDARY','公开正文或截图核对，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N049-09','CN0026','S049-06','企业部门入口','官网联系我们','销售一部、销售二部、山东分公司、技术市场部公开列示；收录企业官方邮箱与表单，未采集个人手机。可向企业公共渠道询问技术市场部，非现任环保负责人确认。','WEB_COMPANY','公开正文或截图核对，未归档原件','2026-11-28');
